/** Authored places and neighborhood details. No simulation state lives here. */
const reward=(credits=0,ore=0,crystal=0,heal=0)=>({credits,ore,crystal,heal});
const record=(id,name,text,x=12,y=8)=>({id,name,text,x,y});
const cache=(id,name,text,value,x=34,y=24)=>({id,name,text,reward:value,x,y});
const place=(id,name,kind,tileX,tileY,summary,story,extra={})=>({id,name,kind,tileX,tileY,summary,story,...extra});

