export function planetPlaces(body){return PLANET_PLACES[body?.id]||[];}
export function districtNames(body){return DISTRICT_NAMES[body?.id]||(/ice|snow|froz/.test(body?.biome||'')?['Field Cooperative','Heat Road','Ice Ridge','Meltwater Flats']:/desert|arid/.test(body?.biome||'')?['Well Cooperative','Water Road','Wind Ridge','Dry Basin']:/volcan/.test(body?.biome||'')?['Ash Cooperative','Glass Road','Heat Ridge','Old Flow']:['Field Cooperative','Growers’ Road','Ridge Country','Outer Flats']);}
